#include "bepio_mn316_session.h"
#include "bepio_mn316_config.h"
#include "mn316.h"
#include <assert.h>
#include <errno.h>
#include <stdio.h>
#include <string.h>

/* Embed a stand-in CA with the exact symbols generated by ESP-IDF. */
__asm__(".global _binary_emqx_ca_pem_start\n_binary_emqx_ca_pem_start:\n.byte 1,0\n"
	".global _binary_emqx_ca_pem_end\n_binary_emqx_ca_pem_end:\n");

enum { NORMAL, AUTH_REJECT, SUB_REJECT, READ_FAIL, WRITE_FAIL };
static int mode, reads, transport_calls;
static unsigned char input[32], output[4096];
static size_t input_size, input_used, output_size;
static int64_t now;

int64_t esp_timer_get_time(void) { now += 1000; return now; }

static int stream_read(void *context, unsigned char *data, size_t size)
{
	(void)context;
	if (mode == READ_FAIL) return -EIO;
	if (++reads % 3 == 0 || input_used == input_size) return -ETIMEDOUT;
	/* Force split fixed headers, lengths, CONNACK and SUBACK across reads. */
	size_t count = size < 2 ? size : 2;
	if (count > input_size - input_used) count = input_size - input_used;
	memcpy(data, input + input_used, count);
	input_used += count;
	return (int)count;
}

static int stream_write(void *context, const unsigned char *data, size_t size)
{
	(void)context;
	if (mode == WRITE_FAIL) return -EIO;
	size_t count = size < 7 ? size : 7;
	assert(output_size + count <= sizeof(output));
	memcpy(output + output_size, data, count);
	output_size += count;
	return (int)count;
}

int bepio_mn316_driver_tls(const bepio_mn316_transport_config_t *config,
	int (*session)(void *, const bepio_mn316_stream_t *), void *context)
{
	transport_calls++;
	assert(!strcmp(config->host, BEPIO_MN316_EMQX_HOST));
	assert(config->port == 8883 && config->ca_size == 2);
	const bepio_mn316_stream_t stream = {NULL, stream_read, stream_write};
	return session(context, &stream);
}

static size_t check_field(const unsigned char *body, size_t size, const char *expected)
{
	size_t count = ((size_t)body[0] << 8) | body[1];
	assert(size >= 2 && count + 2 <= size);
	assert(count == strlen(expected) && !memcmp(body + 2, expected, count));
	return count + 2;
}

static void check_packets(bool expect_publish)
{
	size_t offset = 0;
	unsigned connects = 0, publishes = 0, subscriptions = 0, disconnects = 0;
	while (offset < output_size) {
		unsigned char type = output[offset++], digit;
		size_t size = 0, shift = 0;
		do {
			assert(offset < output_size && shift <= 21);
			digit = output[offset++]; size |= (size_t)(digit & 127) << shift; shift += 7;
		} while (digit & 128);
		assert(offset + size <= output_size);
		const unsigned char *body = output + offset;
		if (type == 0x10) {
			connects++;
			assert(size >= 10 && body[6] == 4 && body[7] == 0xc2 && body[9] == 60);
			size_t n = 10;
			n += check_field(body + n, size - n, "100000000000001");
			n += check_field(body + n, size - n, "unit-user");
			n += check_field(body + n, size - n, "unit-password");
			assert(n == size);
		} else if (type == 0x82) {
			subscriptions++;
			assert(body[0] == 0 && body[1] == 1);
			size_t n = 2 + check_field(body + 2, size - 2, "pager/demo/100000000000001/inbox");
			assert(n + 1 == size && body[n] == 0);
		} else if (type == 0x30) {
			publishes++;
			size_t n = check_field(body, size, "pager/demo/100000000000002/inbox");
			struct bepio_pager_message message;
			assert(!bepio_pager_message_parse(body + n, size - n, &message));
			assert(!strcmp(message.from, "100000000000001") && !strcmp(message.to, "100000000000002"));
			assert(!strcmp(message.text, "hahaha") && !message.has_location);
		} else {
			assert(type == 0xe0 && size == 0); disconnects++;
		}
		offset += size;
	}
	assert(connects == 1);
	assert(publishes == (expect_publish ? 1u : 0u));
	if (expect_publish) assert(subscriptions == 1 && disconnects == 1);
}

int main(void)
{
	const bepio_mn316_tls_credentials_t credentials = {
		.username = "unit-user", .password = "unit-password",
		.device_id = "100000000000001", .test_text = "hahaha",
	};
	for (mode = NORMAL; mode <= WRITE_FAIL; mode++) {
		reads = transport_calls = 0; input_used = output_size = 0; now = 0;
		const unsigned char responses[] = {0x20, 2, 0, 0, 0x90, 3, 0, 1, 0};
		memcpy(input, responses, sizeof(responses)); input_size = sizeof(responses);
		if (mode == AUTH_REJECT) input[3] = 5;
		if (mode == SUB_REJECT) input[8] = 0x80;
		int ret = bepio_mn316_session_run(&credentials, 1);
		assert(transport_calls == 1);
		assert(mode == NORMAL ? ret == 0 : ret < 0);
		if (mode == AUTH_REJECT) assert(ret == -EACCES);
		if (mode != WRITE_FAIL) check_packets(mode == NORMAL);
	}
	transport_calls = 0;
	assert(bepio_mn316_session_run(NULL, 1) == -EINVAL && transport_calls == 0);
	puts("PASS: manager MQTT CONNECT identity, partial reads/writes, timeouts, auth rejection, own inbox, JSON target and clean disconnect");
	return 0;
}
